/**
 * VERSION 3 PLAN - Oracle adapter (skeleton, not wired yet).
 *
 * Goal: run the whole app against a local Oracle database (e.g. Oracle Database Free 23ai in Docker)
 * by setting DB_DRIVER=oracle - no route, AI or UI code changes, because everything talks to the `Db` interface.
 *
 * Steps to finish it:
 *   1. npm install oracledb   (node-oracledb "Thin" mode needs no Oracle Client install)
 *   2. Create the schema:      sqlplus user/pass@localhost:1521/FREEPDB1 @db/oracle/schema.sql
 *   3. Load the data:          @db/oracle/data.sql   (generated by `npm run db:export-oracle` from the sheet or local DB)
 *   4. Implement the methods below and register 'oracle' in server/src/db/index.ts.
 *
 * Mapping (identical to Sheets / local JSON, see shared/schema.ts):
 *   table name      -> same name (unquoted, Oracle stores it upper-case)
 *   'id' / 'string' -> VARCHAR2(n)      'text' -> CLOB          'json' -> CLOB CHECK (col IS JSON)
 *   'int'           -> NUMBER(10)       'number'/'money' -> NUMBER
 *   'bool'          -> CHAR(1) 'Y'/'N'  'date' -> DATE          'datetime' -> TIMESTAMP
 *   Convert DATE/TIMESTAMP back to 'YYYY-MM-DD' / ISO strings when reading so the app sees the same shapes.
 *
 * Method sketch with node-oracledb:
 *   all(table)            SELECT * FROM table WHERE is_deleted = 'N'          (outFormat: OBJECT, lower-case keys)
 *   get(table, id)        SELECT * FROM table WHERE <pk> = :id
 *   find(table, pred)     all() then filter in JS (fine for prototype volumes; push filters to SQL later)
 *   insert(table, row)    id = nextId(prefix, SELECT <pk> FROM table)  -> INSERT ... VALUES (:binds)
 *   update(table, id, p)  UPDATE table SET col = :col, updated_at = SYSTIMESTAMP WHERE <pk> = :id
 *   softDelete            UPDATE table SET is_deleted = 'Y'
 *   Use a connection pool (oracledb.createPool) and autoCommit for single statements.
 */
import type { TableName } from '../../../../shared/schema';
import type { Db, Row } from '../Db';

export class OracleAdapter implements Db {
  readonly driver = 'oracle' as const;
  private fail(): never { throw new Error('OracleAdapter is planned for version 3. See docs/ORACLE_MIGRATION.md.'); }
  async init(): Promise<void> { this.fail(); }
  async all<T extends Row = Row>(_t: TableName): Promise<T[]> { this.fail(); }
  async find<T extends Row = Row>(_t: TableName, _p: (row: T) => boolean): Promise<T[]> { this.fail(); }
  async get<T extends Row = Row>(_t: TableName, _id: string): Promise<T | undefined> { this.fail(); }
  async insert<T extends Row = Row>(_t: TableName, _r: Partial<T>): Promise<T> { this.fail(); }
  async insertMany<T extends Row = Row>(_t: TableName, _r: Partial<T>[]): Promise<T[]> { this.fail(); }
  async update<T extends Row = Row>(_t: TableName, _id: string, _p: Partial<T>): Promise<T> { this.fail(); }
  async softDelete(_t: TableName, _id: string): Promise<void> { this.fail(); }
  async counts(): Promise<Record<string, number>> { this.fail(); }
  async reload(): Promise<void> { this.fail(); }
}
